import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str_in = scanner.nextLine();
        StringBuilder str_out = new StringBuilder();
        boolean at_marker = false;
        str_in += "###";

        for (int i = 0; i < str_in.length() - 3; i++) {
            if (str_out.length() == 0) {
                str_out.append(str_in.charAt(i));
                continue;
            }
            if (str_in.charAt(i) == 'd' && str_in.charAt(i + 1) == 'o' && str_in.charAt(i + 2) == 't') {
                str_out.append('.');
                i += 2;
            } else if (str_in.charAt(i) == 'a' && str_in.charAt(i + 1) == 't' && !at_marker) {
                at_marker = true;
                str_out.append('@');
                i += 1;
            } else {
                str_out.append(str_in.charAt(i));
            }
        }
        if (str_out.length() > 0 && str_out.charAt(str_out.length() - 1) == '.') {
            str_out.setCharAt(str_out.length() - 1, 'd');
            str_out.append("ot");
        }
        System.out.println(str_out.toString());
        scanner.close();
    }
}
